export const messageCase=id=>MESSAGE_CASES.find(c=>c.id===id)||null;
export const messageCard=(c,id)=>c?.cards.find(card=>card.id===id)||null;
export const messageClue=(c,id)=>c?.clues.find(clue=>clue.id===id)||null;
